                }),
                onSnapshot(collection(db, 'users', user.uid, 'purchases'), (snapshot) => {
                    setPurchases(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data(), date: (doc.data().date as Timestamp).toDate() } as Purchase)));
                }),
                onSnapshot(collection(db, 'users', user.uid, 'sales'), (snapshot) => {
                    setSales(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data(), date: (doc.data().date as Timestamp).toDate() } as Sale)));
                }),
                onSnapshot(collection(db, 'users', user.uid, 'invoices'), (snapshot) => {
                    setInvoices(snapshot.docs.map(doc => {
                        const data = doc.data();
