                    }
                }),
            ];

            return () => unsubscribers.forEach(unsub => unsub());
        } else {
            // Clear data on logout (though logout is removed, keeping this logic for safety)
            setItems([]);
            setPurchases([]);
            setSales([]);
            setInvoices([]);
            setSettings(defaultSettings);
