import { collection, onSnapshot, doc, addDoc, updateDoc, deleteDoc, writeBatch, Timestamp, getDocs, setDoc } from 'firebase/firestore';
import type { Item, Purchase, Sale, DashboardData, SummaryMetrics, Transaction, Invoice, Settings, BulkEditChanges, ReportType } from './types';
