    const handleUpdateItemAndCloseModal = async (itemId: string, itemData: Omit<Item, 'id'>) => {
        setIsProcessing(true);
        try {
            await handleUpdateItem(itemId, itemData);
            setIsItemEditModalOpen(false);
            setItemToEdit(null);
        } catch (error) {
