        setIsProcessing(true);

        const addLocal = () => {
             const newTransactions = transactions.map(t => ({
                ...t,
                id: `local_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
            }));
            if (type === 'purchase') {
                setPurchases(prev => [...prev, ...newTransactions as Purchase[]]);
            } else {
                setSales(prev => [...prev, ...newTransactions as Sale[]]);
            }
        };

        try {
            if (isOffline) {
                addLocal();
            } else {
                try {
                    const batch = writeBatch(db);
                    const colName = type === 'purchase' ? 'purchases' : 'sales';
                    const colRef = collection(db, 'users', user.uid, colName);

                    transactions.forEach(t => {
                        const docRef = doc(colRef);
                        batch.set(docRef, t);
                    });

                    await batch.commit();
                } catch (error: any) {
                    if (error.code === 'permission-denied' || error.code === 'unavailable') {
                        console.warn("Write permission denied. Switching to offline mode.");
                        setIsOffline(true);
                        addLocal();
                    } else {
                        throw error;
                    }
                }
            }
        } catch (error) {
            console.error("Error adding transactions:", error);
            alert("Failed to add entries. Please check your connection and try again.");
