    const handleConfirmDelete = async () => {
        if (!deleteConfirmation || !user) return;

        setIsProcessing(true);

        const deleteLocal = () => {
             switch (deleteConfirmation.type) {
                case 'transaction': {
                    const entry = deleteConfirmation.target as Transaction;
                    if (entry.type === 'purchase') {
                        setPurchases(prev => prev.filter(p => p.id !== entry.id));
                    } else {
                        setSales(prev => prev.filter(s => s.id !== entry.id));
                    }
                    break;
                }
                case 'invoice': {
                    const invoice = deleteConfirmation.target as Invoice;
                    setInvoices(prev => prev.filter(i => i.id !== invoice.id));
                    break;
                }
                case 'item': {
                    const item = deleteConfirmation.target as Item;
                    setItems(prev => prev.filter(i => i.id !== item.id));
                    break;
                }
                case 'bulk-transaction': {
                     setPurchases(prev => prev.filter(p => !selectedTransactionIds.has(`purchase-${p.id}`)));
                     setSales(prev => prev.filter(s => !selectedTransactionIds.has(`sale-${s.id}`)));
                    setSelectedTransactionIds(new Set());
                    break;
                }
            }
        };

        try {
            if (isOffline) {
                deleteLocal();
            } else {
                try {
                    switch (deleteConfirmation.type) {
                        case 'transaction': {
                            const entry = deleteConfirmation.target as Transaction;
                            const collectionName = entry.type === 'purchase' ? 'purchases' : 'sales';
                            const docRef = doc(db, 'users', user.uid, collectionName, entry.id);
                            await deleteDoc(docRef);
                            break;
                        }
                        case 'invoice': {
                            const invoice = deleteConfirmation.target as Invoice;
                            const docRef = doc(db, 'users', user.uid, 'invoices', invoice.id);
                            await deleteDoc(docRef);
                            break;
                        }
                        case 'item': {
                            const item = deleteConfirmation.target as Item;
                            const docRef = doc(db, 'users', user.uid, 'items', item.id);
                            await deleteDoc(docRef);
                            break;
                        }
                        case 'bulk-transaction': {
                            if (selectedTransactionIds.size === 0) return;
                            const batch = writeBatch(db);
                            selectedTransactionIds.forEach(id => {
                                const [type, docId] = id.split('-');
                                const collectionName = type === 'purchase' ? 'purchases' : 'sales';
                                const docRef = doc(db, 'users', user.uid, collectionName, docId);
                                batch.delete(docRef);
                            });
                            await batch.commit();
                            setSelectedTransactionIds(new Set());
                            break;
                        }
                    }
                } catch (error: any) {
                    if (error.code === 'permission-denied' || error.code === 'unavailable') {
                        console.warn("Write permission denied. Switching to offline mode.");
                        setIsOffline(true);
                        deleteLocal();
                    } else {
                        throw error;
                    }
                }
            }
            setDeleteConfirmation(null); // Close modal on success
        } catch (error) {
            console.error("Error during deletion:", error);
            alert("Failed to delete. Please check your connection and try again.");
            // On error, modal stays open because state is not cleared
        } finally {
            setIsProcessing(false);
        }
    };


    // --- Invoice Handlers ---
    const handleCreateInvoice = async (invoice: Omit<Invoice, 'id' | 'date'>) => {
        if (!user) return;
        setIsProcessing(true);

        const createLocal = () => {
             const newInvoiceId = `local_inv_${Date.now()}`;
             const finalInvoice: Invoice = { ...invoice, id: newInvoiceId, date: new Date() };
             setInvoices(prev => [...prev, finalInvoice]);

             const newSales: Sale[] = invoice.items.map(item => {
                const [itemId] = item.id.split(`-${item.color}-${item.size}`);
                return {
                    id: `local_sale_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
                    itemId,
                    quantity: item.quantity,
                    salePrice: item.price,
                    date: new Date(),
                    color: item.color,
                    size: item.size,
                    customerName: invoice.customer.name,
                    discountType: item.discountType,
                    discountValue: item.discountType === 'rupees' 
                        ? (item.discountValue || 0) * item.quantity 
                        : item.discountValue,
                };
             });
             setSales(prev => [...prev, ...newSales]);
             setSettings(prev => ({ ...prev, invoiceNextNumber: (prev.invoiceNextNumber || 1) + 1 }));

             setInvoiceToPreview(finalInvoice);
             setIsInvoiceModalOpen(false);
        };

        try {
            if (isOffline) {
                 createLocal();
            } else {
                try {
                    const batch = writeBatch(db);

                    // 1. Add invoice to Firestore
                    const invoiceRef = doc(collection(db, 'users', user.uid, 'invoices'));
                    const finalInvoice: Invoice = { ...invoice, id: invoiceRef.id, date: new Date() };
                    batch.set(invoiceRef, finalInvoice);

                    // 2. Create corresponding sales transactions
                    const salesColRef = collection(db, 'users', user.uid, 'sales');
                    invoice.items.forEach(item => {
                        const [itemId] = item.id.split(`-${item.color}-${item.size}`);
                        const saleDocRef = doc(salesColRef);
                        const saleData: Omit<Sale, 'id'> = {
                            itemId,
                            quantity: item.quantity,
                            salePrice: item.price,
                            date: new Date(),
                            color: item.color,
                            size: item.size,
                            customerName: invoice.customer.name,
                            discountType: item.discountType,
                            // For 'rupees', the invoice value is per-item, but Sale object needs the total discount for the line.
                            discountValue: item.discountType === 'rupees' 
                                ? (item.discountValue || 0) * item.quantity 
                                : item.discountValue,
                        };
                        batch.set(saleDocRef, saleData);
                    });

                    // 3. Update next invoice number in settings
                    const settingsRef = doc(db, 'users', user.uid, 'settings', 'config');
                    batch.update(settingsRef, { invoiceNextNumber: (settings.invoiceNextNumber || 1) + 1 });

                    await batch.commit();

                    setInvoiceToPreview(finalInvoice);
                    setIsInvoiceModalOpen(false);
                } catch (error: any) {
                    if (error.code === 'permission-denied' || error.code === 'unavailable') {
                        console.warn("Write permission denied. Switching to offline mode.");
                        setIsOffline(true);
                        createLocal();
                    } else {
                        throw error;
                    }
                }
            }
        } catch (error) {
            console.error("Error creating invoice:", error);
            alert("Failed to create invoice.");
            throw error;
        } finally {
            setIsProcessing(false);
        }
    };

