                            {isOffline && (
                                <span className="px-2 py-1 bg-amber-100 text-amber-800 text-xs font-bold rounded-full border border-amber-300">
                                    Offline Mode
                                </span>
                            )}
                        </div>
                        <p className="text-slate-500 dark:text-slate-400">Your clothing shop's financial overview.</p>
                    </div>
                    <div className="flex items-center gap-2 sm:gap-4">
                        <LogoUploader
                            logo={businessLogo}
                            onLogoUpload={handleLogoUpload}
                            onLogoRemove={() => handleSetLogo(null)}
                            isProcessing={isLogoProcessing}
                        />
                         <button
                            onClick={() => handleOpenReport('sales')}
                            className="flex items-center gap-2 px-4 py-2 bg-slate-600 text-white font-semibold rounded-lg shadow-md hover:bg-slate-700 focus:outline-none focus:ring-2 focus:ring-slate-500 focus:ring-offset-2 focus:ring-offset-slate-50 dark:focus:ring-offset-slate-900 transition-colors"
                        >
                            <DocumentTextIcon className="w-5 h-5" />
                            <span className="hidden sm:inline">Generate Report</span>
                        </button>
                         <button
                            onClick={openAddInvoiceModal}
                            className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white font-semibold rounded-lg shadow-md hover:bg-emerald-700 focus:outline-none focus:ring-2 focus:ring-emerald-500 focus:ring-offset-2 focus:ring-offset-slate-50 dark:focus:ring-offset-slate-900 transition-colors"
                        >
                            <InvoiceIcon className="w-5 h-5" />
