            />
            <InvoicePreviewModal
                isOpen={!!invoiceToPreview}
                onClose={() => setInvoiceToPreview(null)}
                invoiceData={invoiceToPreview}
                businessLogo={businessLogo}
                settings={settings}
            />
            <ConfirmationModal
                isOpen={!!deleteConfirmation}
                onClose={() => setDeleteConfirmation(null)}
                onConfirm={handleConfirmDelete}
