  ]
}

import React, { useEffect, useState, useRef } from 'react';
import QRCode from 'qrcode';
import JsBarcode from 'jsbarcode';
import type { DashboardData } from '../types';
import { XIcon } from './icons/XIcon';

interface QrCodeModalProps {
    isOpen: boolean;
    onClose: () => void;
    itemData: DashboardData | null;
    businessLogo: string | null;
}

const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-IN', {
        style: 'currency',
        currency: 'INR',
    }).format(amount);
};

const QrCodeModal: React.FC<QrCodeModalProps> = ({ isOpen, onClose, itemData, businessLogo }) => {
    const [qrCodeUrl, setQrCodeUrl] = useState('');
    const barcodeRef = useRef<SVGSVGElement>(null);

    // Settings State
    const [labelWidth, setLabelWidth] = useState(50); // mm
    const [labelHeight, setLabelHeight] = useState(50); // mm
    const [codeSize, setCodeSize] = useState(30); // mm (width/height for QR, height for Barcode)
    const [format, setFormat] = useState<'qr' | 'barcode'>('qr');
    const [fontSize, setFontSize] = useState(12);

    useEffect(() => {
        if (isOpen && itemData) {
            if (format === 'qr') {
                const qrData = JSON.stringify({
                    variantId: itemData.variantId,
                    name: itemData.name,
                    color: itemData.color,
                    size: itemData.size,
                });
                QRCode.toDataURL(qrData, { width: 400, margin: 1 }, (err, url) => {
                    if (err) console.error('QR Code generation failed:', err);
                    else setQrCodeUrl(url);
                });
            } else {
                if (barcodeRef.current) {
                    try {
                        JsBarcode(barcodeRef.current, itemData.variantId, {
                            format: "CODE128",
                            width: 2,
                            height: 50,
                            displayValue: true,
                            fontSize: 12,
                            margin: 0,
                            background: "transparent"
                        });
                    } catch (e) {
                        console.error("Barcode generation failed", e);
                    }
                }
            }
        }
    }, [isOpen, itemData, format]);

    const handlePrint = () => {
        window.print();
    };

    const handleSwapDimensions = () => {
        setLabelWidth(labelHeight);
        setLabelHeight(labelWidth);
    };

    if (!isOpen || !itemData) return null;

    const hasDiscount = itemData.discountPercentage && itemData.discountPercentage > 0 && itemData.saleRealPrice;

    return (
        <>
            <style>
                {`
                @media print {
                  body {
                    background: white !important;
                  }
                  .no-print {
                    display: none !important;
                  }
                  .print-container {
                    position: static !important;
                    background: transparent !important;
                    padding: 0 !important;
                    display: block !important;
                  }
                  body * {
                    visibility: hidden;
                  }
                  #printable-qr-area, #printable-qr-area * {
                    visibility: visible;
                  }
                  #printable-qr-area {
                    position: absolute;
                    left: 0;
                    top: 0;
                    width: ${labelWidth}mm;
                    height: ${labelHeight}mm;
                    overflow: hidden;
                    border: none !important;
                    margin: 0;
                  }
                   .printable-content {
                     background: white !important;
                     width: 100%;
                     height: 100%;
                     display: flex;
                     flex-direction: column;
                     justify-content: center;
                     align-items: center;
                     padding: 2mm;
                     box-sizing: border-box;
                   }
                   @page {
                     size: ${labelWidth}mm ${labelHeight}mm;
                     margin: 0;
                   }
                }
              `}
            </style>
            <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4 print-container" onClick={onClose}>
                <div className="bg-white dark:bg-slate-800 rounded-lg shadow-2xl p-6 w-full max-w-4xl max-h-[90vh] flex flex-col md:flex-row gap-6 overflow-y-auto no-print" onClick={e => e.stopPropagation()}>

                    {/* Settings Panel */}
                    <div className="w-full md:w-1/3 space-y-4 border-r border-slate-200 dark:border-slate-700 pr-0 md:pr-6">
                        <div className="flex justify-between items-center">
                            <h3 className="text-lg font-bold text-slate-900 dark:text-white">Label Settings</h3>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Code Format</label>
                            <div className="flex rounded-md shadow-sm" role="group">
                                <button
                                    type="button"
                                    onClick={() => setFormat('qr')}
                                    className={`px-4 py-2 text-sm font-medium border border-slate-300 dark:border-slate-600 rounded-l-lg ${format === 'qr' ? 'bg-indigo-600 text-white' : 'bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-600'}`}
                                >
                                    QR Code
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setFormat('barcode')}
                                    className={`px-4 py-2 text-sm font-medium border border-l-0 border-slate-300 dark:border-slate-600 rounded-r-lg ${format === 'barcode' ? 'bg-indigo-600 text-white' : 'bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-600'}`}
                                >
                                    Barcode
                                </button>
                            </div>
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Width (mm)</label>
                                <input type="number" value={labelWidth} onChange={e => setLabelWidth(Number(e.target.value))} className="w-full px-3 py-2 bg-white dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded-md text-sm" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Height (mm)</label>
                                <input type="number" value={labelHeight} onChange={e => setLabelHeight(Number(e.target.value))} className="w-full px-3 py-2 bg-white dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded-md text-sm" />
                            </div>
                        </div>

                        <button onClick={handleSwapDimensions} className="w-full py-1.5 text-xs bg-slate-200 dark:bg-slate-600 rounded hover:bg-slate-300 dark:hover:bg-slate-500 text-slate-700 dark:text-slate-300">
                            Swap Dimensions (Vertical/Horizontal)
                        </button>

                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Code Size (mm)</label>
                            <input type="number" value={codeSize} onChange={e => setCodeSize(Number(e.target.value))} className="w-full px-3 py-2 bg-white dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded-md text-sm" />
                        </div>
                         <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Font Size (px)</label>
                            <input type="number" value={fontSize} onChange={e => setFontSize(Number(e.target.value))} className="w-full px-3 py-2 bg-white dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded-md text-sm" />
                        </div>

                        <div className="pt-4 flex justify-end gap-2">
                             <button
                                onClick={onClose}
                                className="px-4 py-2 bg-slate-200 dark:bg-slate-600 text-slate-800 dark:text-slate-200 font-semibold rounded-lg hover:bg-slate-300 dark:hover:bg-slate-500 transition-colors"
                            >
                                Close
                            </button>
                            <button
