import React, { useEffect, useState, useRef } from 'react';
import QRCode from 'qrcode';
import JsBarcode from 'jsbarcode';
import type { DashboardData } from '../types';
import { XIcon } from './icons/XIcon';

interface BulkQrCodeModalProps {
    isOpen: boolean;
    onClose: () => void;
    itemsData: DashboardData[];
    businessLogo: string | null;
}

const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-IN', {
        style: 'currency',
        currency: 'INR',
    }).format(amount);
};

interface LabelProps {
    item: DashboardData;
    businessLogo: string | null;
    settings: {
        width: number;
        height: number;
        codeSize: number;
        format: 'qr' | 'barcode';
        fontSize: number;
    };
}

const QrCodeLabel: React.FC<LabelProps> = React.memo(({ item, businessLogo, settings }) => {
    const [qrCodeUrl, setQrCodeUrl] = useState('');
    const barcodeRef = useRef<SVGSVGElement>(null);

    useEffect(() => {
        if (settings.format === 'qr') {
            const qrData = JSON.stringify({
                variantId: item.variantId,
                name: item.name,
                color: item.color,
                size: item.size,
            });
            QRCode.toDataURL(qrData, { width: 200, margin: 1 }, (err, url) => {
                if (err) console.error('QR Code generation failed:', err);
                else setQrCodeUrl(url);
            });
        } else {
             if (barcodeRef.current) {
                try {
                    JsBarcode(barcodeRef.current, item.variantId, {
                        format: "CODE128",
                        width: 1.5, // Thinner bars for small labels
                        height: 40,
                        displayValue: true,
                        fontSize: 10,
                        margin: 0,
                        background: "transparent"
                    });
                } catch (e) {
                    console.error("Barcode generation failed", e);
                }
            }
        }
    }, [item, settings.format]);

    const hasDiscount = item.discountPercentage && item.discountPercentage > 0 && item.saleRealPrice;

    return (
        <div 
            className="qr-label-container bg-white text-black"
            style={{
                width: `${settings.width}mm`,
                height: `${settings.height}mm`,
                border: '1px dashed #ccc',
                padding: '2mm',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'space-between',
                boxSizing: 'border-box',
                overflow: 'hidden',
                pageBreakInside: 'avoid'
            }}
        >
            <div className="flex flex-col items-center w-full" style={{ maxHeight: '20%' }}>
                {businessLogo && <img src={businessLogo} alt="Logo" style={{ height: '12px', objectFit: 'contain', marginBottom: '1px' }} />}
                <h4 style={{ fontSize: `${settings.fontSize}px`, fontWeight: 'bold', lineHeight: 1.1, textAlign: 'center', margin: 0, width: '100%', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{item.name}</h4>
            </div>

            <div className="flex-grow flex items-center justify-center w-full" style={{ margin: '1mm 0' }}>
                {settings.format === 'qr' ? (
                    qrCodeUrl ? (
                        <img src={qrCodeUrl} alt="QR" style={{ width: `${settings.codeSize}mm`, height: `${settings.codeSize}mm`, objectFit: 'contain' }} />
                    ) : (
                        <div style={{ width: `${settings.codeSize}mm`, height: `${settings.codeSize}mm`, background: '#eee' }}></div>
                    )
                ) : (
                     <svg ref={barcodeRef} style={{ width: '100%', height: `${settings.codeSize}mm`, maxWidth: '100%' }}></svg>
                )}
            </div>

            <div className="text-center w-full" style={{ maxHeight: '25%' }}>
                <p style={{ fontSize: `${Math.max(8, settings.fontSize - 3)}px`, color: '#555', margin: 0 }}>{item.color} / {item.size}</p>
                <div style={{ lineHeight: 1 }}>
                     {hasDiscount ? (
                        <>
                            <span style={{ fontSize: `${Math.max(8, settings.fontSize - 3)}px`, textDecoration: 'line-through', color: '#777', marginRight: '2px' }}>
                                {formatCurrency(item.saleRealPrice ?? 0)}
                            </span>
                            <span style={{ fontSize: `${settings.fontSize + 1}px`, fontWeight: 'bold' }}>
                                {formatCurrency(item.sellingPrice ?? 0)}
                            </span>
                        </>
                    ) : (
                        <p style={{ fontSize: `${settings.fontSize + 1}px`, fontWeight: 'bold', margin: 0 }}>
                            {formatCurrency(item.sellingPrice ?? item.avgSalePrice ?? 0)}
                        </p>
                    )}
                </div>
            </div>
        </div>
    );
});

