                        <div style={{ width: `${settings.codeSize}mm`, height: `${settings.codeSize}mm`, background: '#eee' }}></div>
                    )
                ) : (
                     <svg ref={barcodeRef} style={{ width: '100%', height: `${settings.codeSize}mm`, maxWidth: '100%' }}></svg>
                )}
