                  /* Ensure contents are visible */
                  #printable-qr-area * {
                    visibility: visible !important;
                  }

                  @page {
                    size: ${labelWidth}mm ${labelHeight}mm;
                    margin: 0;
                  }
                }
              `}
            </style>
