    // Load settings from localStorage or default
    const getInitialSettings = () => {
        const saved = localStorage.getItem(SETTINGS_KEY);
        if (saved) {
            try {
                return JSON.parse(saved);
            } catch (e) {
                console.error("Failed to parse saved settings", e);
            }
        }
        return {
            labelWidth: 50,
