                });
                QRCode.toDataURL(qrData, { width: 400, margin: 1 }, (err, url) => {
                    if (err) console.error('QR Code generation failed:', err);
                    else setQrCodeUrl(url);
                });
            } else {
                if (barcodeRef.current) {
                    try {
                        JsBarcode(barcodeRef.current, itemData.variantId, {
                            format: "CODE128",
                            width: 2,
