                    position: static !important;
                    box-shadow: none !important;
                    width: auto !important;
                    height: auto !important;
                    margin: 0 !important;
                    padding: 0 !important;
                    overflow: visible !important;
                    display: block !important;
                  }

                  /* Target the printable area specifically */
                  #printable-qr-area {
                    visibility: visible !important;
                    position: absolute !important;
                    left: 0 !important;
                    top: 0 !important;
                    z-index: 9999 !important;
                    background: white !important;
                    margin: 0 !important;
                    padding: 2mm !important; /* Ensure padding is kept */
                    box-shadow: none !important;
                    border: none !important;
                    width: ${labelWidth}mm !important;
                    height: ${labelHeight}mm !important;
                    display: flex !important;
                    flex-direction: column !important;
                    justify-content: center !important;
                    align-items: center !important;
                  }

                  /* Ensure contents are visible and black */
                  #printable-qr-area * {
                    visibility: visible !important;
                    color: black !important;
                  }

                  @page {
                    size: ${labelWidth}mm ${labelHeight}mm;
                    margin: 0;
                  }
                }
              `}
            </style>
            <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" onClick={onClose}>
                <div className="bg-white dark:bg-slate-800 rounded-lg shadow-2xl p-6 w-full max-w-4xl max-h-[90vh] flex flex-col md:flex-row gap-6 overflow-y-auto" onClick={e => e.stopPropagation()}>

