    const handleConfirmDelete = async () => {
        if (!deleteConfirmation || !user) return;

        setIsProcessing(true);

        const deleteLocal = () => {
             switch (deleteConfirmation.type) {
                case 'transaction': {
                    const entry = deleteConfirmation.target as Transaction;
                    if (entry.type === 'purchase') {
                        setPurchases(prev => prev.filter(p => p.id !== entry.id));
                    } else {
                        setSales(prev => prev.filter(s => s.id !== entry.id));
                    }
                    break;
                }
                case 'invoice': {
                    const invoice = deleteConfirmation.target as Invoice;
                    setInvoices(prev => prev.filter(i => i.id !== invoice.id));
                    break;
                }
                case 'item': {
                    const item = deleteConfirmation.target as Item;
                    setItems(prev => prev.filter(i => i.id !== item.id));
                    break;
                }
                case 'bulk-transaction': {
                     setPurchases(prev => prev.filter(p => !selectedTransactionIds.has(`purchase-${p.id}`)));
                     setSales(prev => prev.filter(s => !selectedTransactionIds.has(`sale-${s.id}`)));
                    setSelectedTransactionIds(new Set());
                    break;
                }
            }
        };

        try {
            if (isOffline) {
                deleteLocal();
            } else {
                try {
                    switch (deleteConfirmation.type) {
                        case 'transaction': {
                            const entry = deleteConfirmation.target as Transaction;
                            const collectionName = entry.type === 'purchase' ? 'purchases' : 'sales';
                            const docRef = db.collection('users').doc(user.uid).collection(collectionName).doc(entry.id);
                            await docRef.delete();
                            break;
                        }
                        case 'invoice': {
                            const invoice = deleteConfirmation.target as Invoice;
                            const docRef = db.collection('users').doc(user.uid).collection('invoices').doc(invoice.id);
                            await docRef.delete();
                            break;
                        }
                        case 'item': {
                            const item = deleteConfirmation.target as Item;
                            const docRef = db.collection('users').doc(user.uid).collection('items').doc(item.id);
                            await docRef.delete();
                            break;
                        }
                        case 'bulk-transaction': {
                            if (selectedTransactionIds.size === 0) return;
                            const batch = db.batch();
                            selectedTransactionIds.forEach(id => {
                                const [type, docId] = id.split('-');
                                const collectionName = type === 'purchase' ? 'purchases' : 'sales';
                                const docRef = db.collection('users').doc(user.uid).collection(collectionName).doc(docId);
                                batch.delete(docRef);
                            });
                            await batch.commit();
                            setSelectedTransactionIds(new Set());
                            break;
                        }
                    }
                } catch (error: any) {
                    if (error.code === 'permission-denied' || error.code === 'unavailable') {
                        console.warn("Write permission denied. Switching to offline mode.");
                        setIsOffline(true);
                        deleteLocal();
                    } else {
                        throw error;
                    }
                }
            }
            setDeleteConfirmation(null); // Close modal on success
        } catch (error) {
            console.error("Error during deletion:", error);
            alert("Failed to delete. Please check your connection and try again.");
