    const handleCreateInvoice = async (invoice: Omit<Invoice, 'id' | 'date'>) => {
        if (!user) return;
        setIsProcessing(true);

        const createLocal = () => {
             const newInvoiceId = `local_inv_${Date.now()}`;
             const finalInvoice: Invoice = { ...invoice, id: newInvoiceId, date: new Date() };
             setInvoices(prev => [...prev, finalInvoice]);

             const newSales: Sale[] = invoice.items.map(item => {
                const [itemId] = item.id.split(`-${item.color}-${item.size}`);
                return {
                    id: `local_sale_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
                    itemId,
                    quantity: item.quantity,
                    salePrice: item.price,
                    date: new Date(),
                    color: item.color,
                    size: item.size,
                    customerName: invoice.customer.name,
                    discountType: item.discountType,
                    discountValue: item.discountType === 'rupees' 
                        ? (item.discountValue || 0) * item.quantity 
                        : item.discountValue,
                };
             });
             setSales(prev => [...prev, ...newSales]);
             setSettings(prev => ({ ...prev, invoiceNextNumber: (prev.invoiceNextNumber || 1) + 1 }));

             setInvoiceToPreview(finalInvoice);
             setIsInvoiceModalOpen(false);
        };

        try {
            if (isOffline) {
                 createLocal();
            } else {
                try {
                    const batch = db.batch();

                    // 1. Add invoice to Firestore
                    const invoicesColRef = db.collection('users').doc(user.uid).collection('invoices');
                    const invoiceRef = invoicesColRef.doc();
                    const finalInvoice: Invoice = { ...invoice, id: invoiceRef.id, date: new Date() };
                    batch.set(invoiceRef, finalInvoice);

                    // 2. Create corresponding sales transactions
                    const salesColRef = db.collection('users').doc(user.uid).collection('sales');
                    invoice.items.forEach(item => {
                        const [itemId] = item.id.split(`-${item.color}-${item.size}`);
                        const saleDocRef = salesColRef.doc();
                        const saleData: Omit<Sale, 'id'> = {
                            itemId,
                            quantity: item.quantity,
                            salePrice: item.price,
                            date: new Date(),
                            color: item.color,
                            size: item.size,
                            customerName: invoice.customer.name,
                            discountType: item.discountType,
                            // For 'rupees', the invoice value is per-item, but Sale object needs the total discount for the line.
                            discountValue: item.discountType === 'rupees' 
                                ? (item.discountValue || 0) * item.quantity 
                                : item.discountValue,
                        };
                        batch.set(saleDocRef, saleData);
                    });

                    // 3. Update next invoice number in settings
                    const settingsRef = db.collection('users').doc(user.uid).collection('settings').doc('config');
                    batch.update(settingsRef, { invoiceNextNumber: (settings.invoiceNextNumber || 1) + 1 });

                    await batch.commit();

                    setInvoiceToPreview(finalInvoice);
                    setIsInvoiceModalOpen(false);
                } catch (error: any) {
                    if (error.code === 'permission-denied' || error.code === 'unavailable') {
                        console.warn("Write permission denied. Switching to offline mode.");
                        setIsOffline(true);
                        createLocal();
                    } else {
                        throw error;
                    }
                }
            }
        } catch (error) {
            console.error("Error creating invoice:", error);
            alert("Failed to create invoice.");
            throw error;
        } finally {
            setIsProcessing(false);
        }
    };

